import AppKit
import CryptoKit
import Observation
import os

/// Something copied that the Clipboard section can keep: text, a link, or an image (as PNG data).
public enum ShelfClipboardInput: Equatable, Sendable {
    case text(String)
    case link(URL)
    case image(Data)
}

/// Reads the newest copy from a pasteboard, skipping what password managers and other apps mark as private.
public enum ShelfClipboardReader {
    public enum Result: Equatable, Sendable {
        case input(ShelfClipboardInput)
        /// Concealed, transient or generated by an app (nspasteboard.org markers), or nothing we keep.
        case skipped
        case tooLarge
    }

    /// The nspasteboard.org markers, plus older ones some password managers still write.
    public static let privateTypes: Set<String> = [
        "org.nspasteboard.ConcealedType",
        "org.nspasteboard.TransientType",
        "org.nspasteboard.AutoGeneratedType",
        "com.agilebits.onepassword",
        "de.petermaurer.TransientPasteboardType",
    ]
    public static let maxTextLength = 100_000
    /// Images are kept as PNG, scaled down to this many points on the longest side first.
    public static let maxImageSide: CGFloat = 2048
    public static let maxImageBytes = 8_000_000

    public static func read(_ pasteboard: NSPasteboard) -> Result {
        guard let types = pasteboard.types, !types.isEmpty else { return .skipped }
        if types.contains(where: { privateTypes.contains($0.rawValue) }) { return .skipped }
        // Copied files stay where they are: the Shelf already takes them by drag.
        if types.contains(.fileURL) { return .skipped }
        if types.contains(.png) || types.contains(.tiff), !types.contains(.string) {
            guard let data = pasteboard.data(forType: .png) ?? pasteboard.data(forType: .tiff) else { return .skipped }
            guard let png = compressedImage(data) else { return .tooLarge }
            return .input(.image(png))
        }
        guard let string = pasteboard.string(forType: .string) else { return .skipped }
        return classify(string)
    }

    static func classify(_ string: String) -> Result {
        let trimmed = string.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else { return .skipped }
        guard trimmed.count <= maxTextLength else { return .tooLarge }
        if !trimmed.contains(where: \.isWhitespace), let url = URL(string: trimmed),
           let scheme = url.scheme?.lowercased(), ["http", "https"].contains(scheme), url.host != nil {
            return .input(.link(url))
        }
        return .input(.text(string))
    }

    /// PNG data no bigger than `maxImageBytes`, scaled down if it's very large; nil if it still won't fit.
    static func compressedImage(_ data: Data) -> Data? {
        guard let image = NSImage(data: data), let rep = NSBitmapImageRep(data: data) else { return nil }
        let pixels = CGSize(width: rep.pixelsWide, height: rep.pixelsHigh)
        let scale = min(1, maxImageSide / max(pixels.width, pixels.height, 1))
        var png: Data?
        if scale >= 1 {
            png = rep.representation(using: .png, properties: [:])
        } else {
            let size = CGSize(width: (pixels.width * scale).rounded(), height: (pixels.height * scale).rounded())
            guard let scaled = NSBitmapImageRep(
                bitmapDataPlanes: nil, pixelsWide: Int(size.width), pixelsHigh: Int(size.height),
                bitsPerSample: 8, samplesPerPixel: 4, hasAlpha: true, isPlanar: false,
                colorSpaceName: .deviceRGB, bytesPerRow: 0, bitsPerPixel: 0
            ) else { return nil }
            NSGraphicsContext.saveGraphicsState()
            NSGraphicsContext.current = NSGraphicsContext(bitmapImageRep: scaled)
            image.draw(in: CGRect(origin: .zero, size: size))
            NSGraphicsContext.restoreGraphicsState()
            png = scaled.representation(using: .png, properties: [:])
        }
        guard let png, png.count <= maxImageBytes else { return nil }
        return png
    }
}

/// A recent copy in the Shelf's Clipboard section. Pinned ones stay until you unpin or remove them.
public struct ShelfClipboardEntry: Identifiable, Equatable, Sendable {
    public var item: ShelfItem
    public var isPinned: Bool
    public var id: UUID { item.id }
}

/// Clipboard history for the Shelf (#79). While on, it checks `NSPasteboard.changeCount` every 1.5 seconds
/// and keeps the last `length` copies in memory. Images are written to a private folder that's emptied on
/// launch, when history is turned off, and as entries age out. Nothing is kept after PancakeNotch quits.
@MainActor
@Observable
public final class ShelfClipboard {
    public static let pollInterval: TimeInterval = 1.5

    public private(set) var entries: [ShelfClipboardEntry] = []
    public private(set) var isRunning = false
    /// True for a few seconds after a copy was too big to keep.
    public private(set) var showsTooLarge = false
    public var length: Int { didSet { trim() } }
    /// Called after each copy that was kept.
    @ObservationIgnored public var onCopy: ((ShelfClipboardEntry) -> Void)?

    public let directory: URL
    @ObservationIgnored private let pasteboard: NSPasteboard
    @ObservationIgnored private let now: () -> Date
    @ObservationIgnored private var timer: Timer?
    @ObservationIgnored private var lastChangeCount: Int
    /// Image entries by the hash of their PNG, so copying the same image twice moves it to the front.
    @ObservationIgnored private var imageKeys: [UUID: String] = [:]
    @ObservationIgnored private let logger = Logger(subsystem: "io.github.sickpancake.PancakeNotch", category: "shelf")

    public static var defaultDirectory: URL {
        ShelfStore.defaultDirectory.appending(path: "Clipboard", directoryHint: .isDirectory)
    }

    public init(
        directory: URL = ShelfClipboard.defaultDirectory,
        pasteboard: NSPasteboard = .general,
        length: Int = 10,
        now: @escaping () -> Date = Date.init
    ) {
        self.directory = directory
        self.pasteboard = pasteboard
        self.length = length
        self.now = now
        lastChangeCount = pasteboard.changeCount
        try? FileManager.default.removeItem(at: directory)
    }

    /// Keeps `isRunning` and `length` in step with the Shelf's settings for as long as both exist.
    public func follow(_ settings: ShelfSettings) {
        withObservationTracking {
            setRunning(settings.isEnabled && settings.remembersCopies)
            length = settings.clipboardLength
        } onChange: { [weak self, weak settings] in
            Task { @MainActor in
                guard let self, let settings else { return }
                self.follow(settings)
            }
        }
    }

    public func setRunning(_ on: Bool) {
        guard on != isRunning else { return }
        isRunning = on
        timer?.invalidate()
        timer = nil
        if on {
            // What was on the clipboard before you turned this on isn't history.
            lastChangeCount = pasteboard.changeCount
            let timer = Timer(timeInterval: Self.pollInterval, repeats: true) { [weak self] _ in
                MainActor.assumeIsolated { self?.poll() }
            }
            timer.tolerance = 0.5
            RunLoop.main.add(timer, forMode: .common)
            self.timer = timer
        } else {
            removeAll(keepingPinned: false)
        }
    }

    /// Reads the pasteboard if it changed since the last look.
    public func poll() {
        let count = pasteboard.changeCount
        guard count != lastChangeCount else { return }
        lastChangeCount = count
        switch ShelfClipboardReader.read(pasteboard) {
        case .input(let input): record(input)
        case .tooLarge:
            showsTooLarge = true
            Task { [weak self] in
                try? await Task.sleep(for: .seconds(4))
                self?.showsTooLarge = false
            }
        case .skipped: break
        }
    }

    /// Adds a copy at the front; the same text, link or image again moves the old entry up instead.
    @discardableResult
    public func record(_ input: ShelfClipboardInput) -> ShelfClipboardEntry? {
        let key: String
        switch input {
        case .text(let text): key = "text:\(text)"
        case .link(let url): key = "link:\(url.absoluteString)"
        case .image(let data): key = "image:" + SHA256.hash(data: data).map { String(format: "%02x", $0) }.joined()
        }
        if let index = entries.firstIndex(where: { self.key(of: $0) == key }) {
            let entry = entries.remove(at: index)
            entries.insert(entry, at: 0)
            onCopy?(entry)
            return entry
        }
        let item: ShelfItem
        switch input {
        case .text(let text): item = ShelfItem(kind: .text(text), addedAt: now())
        case .link(let url): item = ShelfItem(kind: .link(url), addedAt: now())
        case .image(let data):
            let id = UUID()
            let folder = directory.appending(path: id.uuidString, directoryHint: .isDirectory)
            let url = folder.appending(path: String(localized: "Copied image", comment: "File name for an image kept from the clipboard") + ".png")
            do {
                try FileManager.default.createDirectory(at: folder, withIntermediateDirectories: true)
                try data.write(to: url, options: [.atomic, .completeFileProtection])
                item = ShelfItem(id: id, kind: .file(bookmark: try url.bookmarkData(), owned: true), path: url.path, addedAt: now())
            } catch {
                logger.error("Couldn't keep a copied image: \(error.localizedDescription, privacy: .private)")
                try? FileManager.default.removeItem(at: folder)
                return nil
            }
            imageKeys[id] = key
        }
        let entry = ShelfClipboardEntry(item: item, isPinned: false)
        entries.insert(entry, at: 0)
        trim()
        onCopy?(entry)
        return entry
    }

    public func togglePin(_ id: UUID) {
        guard let index = entries.firstIndex(where: { $0.id == id }) else { return }
        entries[index].isPinned.toggle()
        trim()
    }

    public func remove(_ id: UUID) {
        guard let index = entries.firstIndex(where: { $0.id == id }) else { return }
        discard(entries.remove(at: index))
    }

    /// Clears the history; pinned entries stay unless `keepingPinned` is false.
    public func removeAll(keepingPinned: Bool = true) {
        let (kept, gone) = (entries.filter { keepingPinned && $0.isPinned }, entries.filter { !keepingPinned || !$0.isPinned })
        entries = kept
        gone.forEach(discard)
    }

    /// The file behind an image entry, if it's still there.
    public func fileURL(for entry: ShelfClipboardEntry) -> URL? {
        guard case .file = entry.item.kind, let path = entry.item.path else { return nil }
        let url = URL(fileURLWithPath: path)
        return FileManager.default.fileExists(atPath: path) ? url : nil
    }

    /// Unpinned entries past `length` age out, oldest first.
    private func trim() {
        var unpinned = 0
        var gone: [ShelfClipboardEntry] = []
        entries.removeAll { entry in
            guard !entry.isPinned else { return false }
            unpinned += 1
            if unpinned > max(1, length) { gone.append(entry); return true }
            return false
        }
        gone.forEach(discard)
    }

    private func discard(_ entry: ShelfClipboardEntry) {
        imageKeys[entry.id] = nil
        if case .file = entry.item.kind, let path = entry.item.path {
            try? FileManager.default.removeItem(at: URL(fileURLWithPath: path).deletingLastPathComponent())
        }
    }

    private func key(of entry: ShelfClipboardEntry) -> String {
        imageKeys[entry.id] ?? entry.item.key
    }
}
